  "添加阶段": "ステージを追加",
  "未添加阶段时沿用单次任务。添加后，Agent 按阶段逐次执行；Plan 只生成整体方案。只读阶段限制工具，不允许修改、浏览器、MCP 或子任务。完成表示该阶段回复结束，验收由你评价。": "ステージを追加しない場合は、1回のタスクとして実行されます。追加すると、Agent はステージごとに順に実行します。Plan は全体の計画のみを作成します。読み取り専用のステージでは、変更、ブラウザー、MCP、サブタスクは許可されません。完了は、そのステージの返信が終了したことを意味します。受け入れの判断はあなたが行います。",
