  "仅统计本机记录，参数、聊天内容和评价不写入团队库。回复生成数表示运行时结束；验收数仅来自用户评价。耗时含等待审批与重试间隔，工作区与模型差异可能影响比较。": "集計はこの端末の記録のみが対象です。パラメーター、チャット内容、評価はチームのライブラリに書き込まれません。返信の生成数は実行の終了を表し、受け入れ数はユーザーの評価のみに基づきます。所要時間には承認待ちと再試行の間隔が含まれます。ワークスペースやモデルの違いが比較結果に影響する場合があります。",
