  "团队模板保存到项目的 .vela/team-task-recipes.json，可通过 Git 或共享目录同步。实际访问权限由仓库或文件系统控制；这里的写入开关只限制本机操作。仅共享模板，参数默认值与正文会共享，请勿填写凭据。运行参数、记录、评价与来源聊天不会共享。": "チームのテンプレートはプロジェクトの .vela/team-task-recipes.json に保存され、Git または共有フォルダーで同期できます。実際のアクセス権限はリポジトリやファイルシステムで管理され、ここの書き込みスイッチはこの端末の操作のみを制限します。共有されるのはテンプレートだけで、パラメーターの既定値と本文も共有されるため、認証情報は入力しないでください。実行パラメーター、記録、評価、元のチャットは共有されません。",
