  "已计量表示提供方返回了 Token 用量；覆盖率 = 已计量请求数 / 请求总数。分支对话复制的历史请求只计一次。": "計測済みとは、プロバイダーがトークン使用量を返したことを示します。カバー率 = 計測済みリクエスト数 / 全リクエスト数。会話のブランチにコピーされた履歴のリクエストは 1 回だけ数えます。",
