  "当前对话还没有思考内容总结请求。开启思考总结并完成一段思考后会在这里显示。": "現在の会話にはまだ思考内容の要約リクエストがありません。思考の要約を有効にして思考を完了すると、ここに表示されます。",
  "思考内容总结模型使用统计表": "思考内容の要約モデル使用統計の表",
  "这些请求由思考内容总结功能发起，使用设置中指定的专属总结模型；未指定时使用发起总结时对话选定的模型。它们不计入其他标签页的请求与 Token 统计。": "これらのリクエストは思考内容の要約機能が送信するもので、設定で指定した専用の要約モデルを使用します。指定がない場合は、要約時に会話で選択されていたモデルを使用します。他のタブのリクエストやトークン統計には含まれません。",
