  "仅统计提供方上报的用量，不估算 Token。现有记录无法区分未上报与不支持，因此不支持显示为未知。": "集計対象はプロバイダーが報告した使用量のみで、トークンは推定しません。既存の記録では未報告と非対応を区別できないため、非対応は不明として表示します。",
  "覆盖率反映请求的用量记录完整度。进行中或未返回用量的请求仍计入请求数；Token 总数仅汇总已计量请求。缓存命中率 = 缓存命中 Token / 输入 Token。": "カバー率は、リクエストの使用量記録がどれだけ揃っているかを示します。進行中のリクエストや使用量が返されなかったリクエストもリクエスト数に含まれます。トークン総数は計測済みのリクエストのみを集計します。キャッシュヒット率 = キャッシュヒットのトークン / 入力トークン。",
