  "{0}\n\n## 当前阶段 / Current stage: {1} [{2}] · attempt {3}\n只执行此阶段，后续阶段由运行时单独启动。Only execute this stage; the runtime starts later stages.\n副作用范围 / Effect boundary: {4}\n{5}": "{0}\n\n## 現在の段階 / Current stage: {1} [{2}] · attempt {3}\nこの段階のみを実行します。後続の段階はランタイムが個別に開始します。Only execute this stage; the runtime starts later stages.\n副作用の範囲 / Effect boundary: {4}\n{5}",
  "运行时无法确认阶段结果": "ランタイムは段階の結果を確認できません",
