  "阶段不在等待审批，或该执行已中断": "段階が承認待ちではないか、この実行は中断されています",
  "用户拒绝阶段审批，后续阶段未执行": "ユーザーが段階の承認を拒否したため、後続の段階は実行されませんでした",
  "用户停止任务；不回滚已发生的操作": "ユーザーがタスクを停止しました。既に行われた操作は元に戻しません",
  "停止结果无法保存：{0}": "停止結果を保存できません: {0}",
  "相同重试 ID 不能更换阶段": "同じ再試行 ID で段階を変えることはできません",
  "此阶段正在提交或运行，请稍后检查记录": "この段階は提出中または実行中です。後で記録を確認してください",
  "定时执行失败后请从快照新建手动任务，不重写调度结果": "定期実行が失敗した場合は、スナップショットから手動タスクを新規作成してください。スケジュールの結果は書き換えません",
  "仅已确认失败的只读阶段可限次重试；中断、修改和外部操作需检查后新建任务": "失敗が確認された読み取り専用の段階のみ回数制限付きで再試行できます。中断、変更、外部操作の場合は、確認後に新しいタスクを作成してください",
  "目录、路径、Skill、Git 或模型已变化，请重新预览新任务": "ディレクトリ、パス、Skill、Git、またはモデルが変わりました。新しいタスクを再度プレビューしてください",
