  "{0}（文件不可读取）": "{0}（ファイルを読み取れません）",
  "所需 Skill 不可用：{0}": "必要な Skill が利用できません: {0}",
  "未提交改动审查需在原工作区进行，独立 worktree 不带入这些文件": "未コミットの変更のレビューは元のワークスペースで行う必要があります。独立したワークツリーにはこれらのファイルは含まれません",
  "起始引用必须为有效的 Git 提交": "開始の参照は有効な Git コミットである必要があります",
  "独立 worktree 起始提交：{0}；不带入未提交文件": "独立したワークツリーの開始コミット: {0}。未コミットのファイルは含めません",
  "此路径在起始提交中不存在、类型不符或包含符号链接": "このパスは開始コミットに存在しないか、種類が一致しないか、シンボリックリンクを含みます",
  "独立 worktree 的起始提交或未提交文件与预览不同，任务未提交": "独立したワークツリーの開始コミットまたは未コミットのファイルがプレビューと異なります。タスクは作成されていません",
  "请选择已有本地工作区或 worktree": "既存のローカルのワークスペースまたはワークツリーを選択してください",
  "工作区目录不存在或不可访问": "ワークスペースのディレクトリが存在しないか、アクセスできません",
  "请输入工作区内相对路径": "ワークスペース内の相対パスを入力してください",
  "路径或符号链接越出工作区": "パスまたはシンボリックリンクがワークスペースの外にあります",
  "路径类型不符合要求": "パスの種類が要件を満たしていません",
  "路径不存在或不可访问": "パスが存在しないか、アクセスできません",
  "此内置配方需要包含有效提交的 Git 仓库": "この内蔵レシピには、有効なコミットを含む Git リポジトリが必要です",
  "明确起止提交比较 / Explicit start → end comparison": "開始から終了までのコミットを明示して比較 / Explicit start → end comparison",
  "索引 + 工作区差异 + 未跟踪文件 / Index + working tree + untracked files": "インデックス + 作業ツリーの差分 + 未追跡ファイル / Index + working tree + untracked files",
  "双引用比较必须填写起止引用": "2 つの参照の比較では開始と終了の参照を入力する必要があります",
  "Git 引用不存在或不能解析为提交": "Git の参照が存在しないか、コミットとして解決できません",
  "修复 Bug": "バグを修正",
  "定位问题并限定修复范围，按风险验证。适用于代码或非 Git 工作区。": "原因を特定し、修正範囲を絞り込み、リスクに応じて検証します。コードや Git 以外のワークスペースにも使えます。",
  "问题描述": "問題の説明",
  "复现步骤": "再現手順",
  "预期行为": "期待される動作",
  "关注路径": "注目するパス",
  "在 {{workspace.name}} 修复以下问题：\n{{problem}}": "{{workspace.name}} で次の問題を修正してください:\n{{problem}}",
  "1. 查阅工作区指令与相关实现，结合复现步骤 {{reproduction}} 和预期行为 {{expected}} 查明原因。关注路径：{{focus_path}}。\n2. 限定修复范围；无法复现时说明证据缺口，不猜测已验证。\n3. 实施必要改动。\n4. 按风险和影响范围验证，不默认运行全量测试。": "1. ワークスペースの指示と関連する実装を確認し、再現手順 {{reproduction}}、期待される動作 {{expected}} を踏まえて原因を特定してください。注目するパス：{{focus_path}}。\n2. 修正範囲を限定してください。再現できない場合は、証拠の不足を説明し、検証済みであるかのように推測しないでください。\n3. 必要な変更を実施してください。\n4. リスクと影響範囲に応じて検証し、既定では全テストを実行しないでください。",
  "说明根因、改动、实际执行的验证与结果，以及剩余问题。": "原因、変更内容、実際に行った検証と結果、残っている問題を報告してください。",
  "审查改动": "変更をレビュー",
  "只读审阅未提交改动或两个明确 Git 提交之间的差异，不自动修复。": "未コミットの変更、または 2 つの明示された Git コミット間の差分を読み取り専用でレビューします。自動修正はしません。",
  "审查范围": "レビューの範囲",
  "未提交改动": "未コミットの変更",
  "两个 Git 引用": "2 つの Git 参照",
  "起始引用": "開始の参照",
  "结束引用": "終了の参照",
  "关注点": "注目点",
  "审查 {{workspace.name}} 的 {{scope}}。关注点：{{focus}}。": "{{workspace.name}} の {{scope}} をレビューしてください。注目点: {{focus}}。",
  "1. 按预览中保存的 Git 范围查阅差异与相关代码。双引用使用明确起止 SHA 比较，不使用 merge-base。未提交范围包含索引和工作区差异，并列出未跟踪文件与实际查看范围。\n2. 检查正确性和回归风险。\n3. 汇总发现，不修改文件、不自动修复；沿用 Plan 审阅机制。": "1. プレビューに保存された Git の範囲に従って、差分と関連コードを確認してください。2 つの参照は明示された開始・終了の SHA で比較し、merge-base は使わないでください。未コミットの範囲はインデックスと作業ツリーの両方の差分を含み、未追跡ファイルと実際に確認した範囲を示してください。\n2. 正しさと回帰リスクを確認してください。\n3. ファイルを変更せず、修正も適用せずに発見事項をまとめてください。既存の Plan レビューの仕組みに従ってください。",
  "按严重程度列出问题、文件位置、触发条件和建议。未发现问题时说明检查范围与限制。": "重大度順に、問題、ファイルの位置、発生条件、提案を列挙してください。問題が見つからない場合は、確認した範囲と制限事項を説明してください。",
  "准备发布": "リリースの準備",
  "核对版本与提交范围，准备发布材料；不创建 Tag、不推送、不实际发布。": "バージョンとコミットの範囲を確認し、リリース資料を準備します。タグの作成、プッシュ、リリースの公開は行いません。",
  "目标版本": "対象バージョン",
  "补充说明": "補足説明",
  "为 {{workspace.name}} 准备 {{version}} 的发布材料。补充说明：{{notes}}。": "{{workspace.name}} の {{version}} のリリース資料を準備してください。補足説明: {{notes}}。",
  "1. 核对项目版本规则与保存的起止提交 SHA。使用两个明确提交比较，不自动改为 merge-base。\n2. 整理发布说明草稿。\n3. 列出需要的检查和发布步骤。本次仅准备材料，不创建 Tag、不推送、不发布。": "1. プロジェクトのバージョン規則と、保存された開始・終了コミットの SHA を確認してください。2 つのコミットを明示的に比較し、merge-base に置き換えないでください。\n2. リリースノートの下書きを作成してください。\n3. 必要なチェックとリリース手順を列挙してください。今回は資料の準備のみで、タグの作成、プッシュ、公開は行わないでください。",
  "交付发布说明草稿、版本差异和待完成事项，并明确哪些检查尚未执行。": "リリースノートの下書き、バージョンの差分、未完了の作業を提出し、まだ実行していない検査を明記してください。",
